import{_ as a,c as n,a as r,o as d}from"./app--u3Uwk-L.js";const i={};function c(p,e){return d(),n("div",null,e[0]||(e[0]=[r('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-09-11-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-09-11-资讯日报"><span>2026-09-11 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="王梦迪-ai尚未发现新基础科学" tabindex="-1"><a class="header-anchor" href="#王梦迪-ai尚未发现新基础科学"><span>王梦迪：AI尚未发现新基础科学</span></a></h3><p>王梦迪：当前大模型偏向拟合概率分布中心，低估长尾情况；因基础科研缺乏成熟验证器，AI尚未发现新基础科学，需搭建可验证可复现的科研基础设施。<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=faebba21f25db7451d8eb353f8b1ac4f0d3fa02d57ba287980c69cb6cb5fda76dd35babee4b6&amp;idx=2&amp;mid=2247666942&amp;sn=9852c672d6b4d5e75a1b9ed102e7e347#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="汤森路透推出领域定制大模型" tabindex="-1"><a class="header-anchor" href="#汤森路透推出领域定制大模型"><span>汤森路透推出领域定制大模型</span></a></h3><p>汤森路透推出基于Qwen的领域定制大模型Thomson，性能优于多款主流通用大模型，小版本开源，可帮助企业保障数据主权，应对AI行业竞争。<a href="https://mp.weixin.qq.com/s?__biz=MzIxNzI0ODE4Nw==&amp;chksm=966d7e250d1797596d9a84daed569a8f747cdb0d56ea4a1ff7ce7fad6cc8b7a513b0eb59e3ed&amp;idx=1&amp;mid=2247498950&amp;sn=deca5ef91476f72d4b5374389eb7074f#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="人形机器人ipo收紧-刚上市ceo炮轰同行" tabindex="-1"><a class="header-anchor" href="#人形机器人ipo收紧-刚上市ceo炮轰同行"><span>人形机器人IPO收紧 刚上市CEO炮轰同行</span></a></h3><p>监管收紧人形机器人IPO审批，要求拟上市企业证明具备持续收入、减亏或核心技术创新。刚港股上市的机器人CEO炮轰同行造虚假收入，坑害投资者，透支行业前途。<a href="https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=fadfb481b90387c6216ee4e8086be0c7cc2932d694786e9bc72701a27767bd307389165f6faf&amp;idx=1&amp;mid=2247666942&amp;sn=7411c8b8a0f330f0e2f0a18707a60fda#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="中国智驾叩开欧洲车企供应链大门" tabindex="-1"><a class="header-anchor" href="#中国智驾叩开欧洲车企供应链大门"><span>中国智驾叩开欧洲车企供应链大门</span></a></h3><p>张永伟称中国智驾出海已进入体系化变革新阶段；智驾新程凭借合规、成本、交付优势叩开欧洲头部车企供应链，全球智驾供应链格局正松动。<a href="https://mp.weixin.qq.com/s?__biz=MzU5OTI0NTc3Mg==&amp;chksm=ff921627b4cd5b5890091f698c81978a57f25059b80ec70544bebee3c79b8097405e218f4694&amp;idx=1&amp;mid=2247557910&amp;sn=efe17c4ea6e1980dd9d33973f34d96c0#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="openai杀疯-欲破千禧年数学难题" tabindex="-1"><a class="header-anchor" href="#openai杀疯-欲破千禧年数学难题"><span>OpenAI杀疯 欲破千禧年数学难题</span></a></h3><p>OpenAI确认，攻克纳维-斯托克斯问题后五天内，已在千禧年难题霍奇猜想取得实质性进展；Anthropic也接近解决另一千禧年难题，头部AI实验室数学推理军备竞赛已白热化。<a href="https://mp.weixin.qq.com/s?__biz=Mzg3MTkxMjYzOA==&amp;chksm=cfbe7acb7c210477cafa977339186ffb0dbda05743e1bac063b48ba6ab10b200e72268296332&amp;idx=1&amp;mid=2247518875&amp;sn=bc871c0c566680d558f9d6fdf071cc28#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="陶哲轩怒批openai毁数学开放传统" tabindex="-1"><a class="header-anchor" href="#陶哲轩怒批openai毁数学开放传统"><span>陶哲轩怒批OpenAI毁数学开放传统</span></a></h3><p>陶哲轩称，AI巨头凭借算力优势截胡人类研究方向，摧毁数学界百年开放科学传统，将损害学科长远发展，学界呼吁拒绝无洞见的AI暴力成果。<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f0d787dc165815a9bdbe0a9b1e701052693489d904327cd9bcfbae5b8be5f8d260528ac0247e&amp;idx=2&amp;mid=2652724627&amp;sn=1d3458b8e7c2c2d25185ac75dc8dc2f6#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="anthropic推演-ai时代钱流向有钱人" tabindex="-1"><a class="header-anchor" href="#anthropic推演-ai时代钱流向有钱人"><span>Anthropic推演：AI时代钱流向有钱人</span></a></h3><p>Anthropic推演显示，AI将推高2030年美国GDP增速，但认知型职业会大量失业、工资缩水，经济增长收益更多流向资本，美国公众判断接近中等影响情景。<a href="https://mp.weixin.qq.com/s?__biz=MzA3NTIyODUzNA==&amp;chksm=862f790e713c5747129015da7801e2367d73fbfffab6c24038a618a9e9779b274e8e97bdd44d&amp;idx=2&amp;mid=2649804973&amp;sn=da40618f7f272dc02c9f3bd77942abe6#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="张天翊打造数字世界个人ai身份证" tabindex="-1"><a class="header-anchor" href="#张天翊打造数字世界个人ai身份证"><span>张天翊打造数字世界个人AI身份证</span></a></h3><p>张天翊提出，当前AI能力已足够，稀缺的是用户个人上下文。他推出开源本地优先的Personal Model，即将内测Persom，将其打造成数字世界个人身份证，供所有AI Agent读取用户上下文。<a href="https://mp.weixin.qq.com/s?__biz=MzU5OTI0NTc3Mg==&amp;chksm=ff850beda21e0aeabea38a62857305834ab608258cb80fda59e0d914af0fa66fee3468f306c9&amp;idx=1&amp;mid=2247557917&amp;sn=b4183005e57a71345ad317a1dca6f6ab#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="snowflake入华两年押注企业智能体" tabindex="-1"><a class="header-anchor" href="#snowflake入华两年押注企业智能体"><span>Snowflake入华两年押注企业智能体</span></a></h3><p>Snowflake称，大模型易得，企业特有业务上下文才是AI可信落地的核心；AI不是魔法，不会自动理顺分散数据，企业需先完成数据准备、治理与上下文统一，才能搭建可靠企业级智能体。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bce2132f7cea37c3c0a82d96af8263dc9e7a7c37babd3499e48ae729fc006fc83cff6b312b39&amp;idx=1&amp;mid=2651292730&amp;sn=9116490e3afdc639dc0a142112b5dc0b#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="豆包工作上新三大功能-主打无痛办公" tabindex="-1"><a class="header-anchor" href="#豆包工作上新三大功能-主打无痛办公"><span>豆包工作上新三大功能 主打无痛办公</span></a></h3><p>特工小智：字节两周内为豆包工作更新三大功能，解决AI办公传文件、操作难描述、任务绑设备的痛点，核心是减少交互摩擦，让AI融入真实工作流。<a href="https://mp.weixin.qq.com/s?__biz=MzYyMTY1NDA0Nw==&amp;chksm=fef6eb7e29f2a03df3ad3305a2207bfac9b1e81e0afee1178cb595a81370e9b87d53f2f22dab&amp;idx=1&amp;mid=2247520991&amp;sn=a62314bb973e5146d5aea1eba5e1479c#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="irobot重返ifa-二次定义清洁机器人" tabindex="-1"><a class="header-anchor" href="#irobot重返ifa-二次定义清洁机器人"><span>iRobot重返IFA 二次定义清洁机器人</span></a></h3><p>iRobot称当下清洁机器人行业陷入参数竞赛，偏离解放人力初心。此次携新品、概念机重返市场，回归以人为本，聚焦解决真实痛点，试图二次定义清洁机器人行业。<a href="https://mp.weixin.qq.com/s?__biz=MzU5OTI0NTc3Mg==&amp;chksm=ff2d495f777ec6d37172bae7a864edbb28486804b46693361ea31df305144ebde01aab2dd03f&amp;idx=1&amp;mid=2247557905&amp;sn=5615d90d7586e0501294339596b2ec44#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek-v4-1-flash-成显存杀手" tabindex="-1"><a class="header-anchor" href="#deepseek-v4-1-flash-成显存杀手"><span>DeepSeek V4.1 Flash 成显存杀手</span></a></h3><p>DeepSeek推出V4.1 Flash大模型，靠CED+CSA2全新架构将KV缓存暴降437倍，显存砍去四分之三，算力成本大降，百万Token长上下文性能反超自家旗舰，还超越多个行业顶级模型，改写大模型竞争逻辑。<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=91c2ead35d51897cdd0f096854e0055488b274749bfa5576dcd84ed225a98ec02e5e8e09f560&amp;idx=1&amp;mid=2247744917&amp;sn=c8dd90f2d92df5c8880d11c6f8d9a575#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="meta推muse-ai全天候替你干活" tabindex="-1"><a class="header-anchor" href="#meta推muse-ai全天候替你干活"><span>Meta推Muse：AI全天候替你干活</span></a></h3><p>Meta发布个人AI Agent Muse，扎克伯格称其依托独立云端虚拟机可全天候自主完成任务，主打隐私安全，未来可帮用户赚回成本，通过订阅加交易抽成盈利，现已面向美国用户开放。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bcb7bec1d31a2fbf0d246702636e29ea2cf632e6f99087ed1fe407a3f5f4f23bbfcc3b731df0&amp;idx=2&amp;mid=2651292728&amp;sn=0de09a4c09c7d688407e551e1d375770#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="京东发布狼族军团重做物理ai" tabindex="-1"><a class="header-anchor" href="#京东发布狼族军团重做物理ai"><span>京东发布狼族军团重做物理AI</span></a></h3><p>京东不盲目押注通用人形机器人，选择贴合工况的异构协同物理AI路线，推出全物流链覆盖的狼族机器人集群，成熟产品3年回本，前沿产品率先跑通UE，可规模化复制。<a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;chksm=bce12c8c6b30981b1dcc18960a0f4309415fad4c4d81b18e2d28a33f0791f4feb466cc94e120&amp;idx=1&amp;mid=2651292728&amp;sn=09f813822e886c5edcf65f5c5a746ce7#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="英伟达cpo量产-光模块还能打吗" tabindex="-1"><a class="header-anchor" href="#英伟达cpo量产-光模块还能打吗"><span>英伟达CPO量产 光模块还能打吗？</span></a></h3><p>英伟达推CPO量产解决超算数据中心高电费问题，业内认为未来两年CPO对光模块订单影响极小，二者将长期共存，国内厂商需抓住窗口期补上游短板。<a href="https://mp.weixin.qq.com/s?__biz=MzU3MDkxNzczNw==&amp;chksm=fd557c64b8b3e798f34474c2fd7366a4480b7b84c5973a5d53a408336667af319b7dbbcaef6c&amp;idx=1&amp;mid=2247497078&amp;sn=72d9bbc425858cb5bb5e6b0ac64f241a#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="sglang优化deepseek-v4-1达764-tokens-s" tabindex="-1"><a class="header-anchor" href="#sglang优化deepseek-v4-1达764-tokens-s"><span>SGLang优化DeepSeek-V4.1达764 tokens/s</span></a></h3><p>SGLang团队：经多轮kernel融合优化与DSpark适配，在4×B300 GPU配置下，DeepSeek-V4.1 Flash BS=1吞吐达764 tokens/s，BS=64总吞吐达13473 tokens/s，后续将接入官方新kernel进一步提效<a href="https://mp.weixin.qq.com/s?__biz=MzA4MjY4NTk0NQ==&amp;chksm=9eb485fdfc5fba9c2758cc88efaa0fee6f0ebe0bb584531f04ffbcf025479d98f676b48c8a78&amp;idx=1&amp;mid=2247532351&amp;sn=5c975540efde1b6c2494cd92d24a5a5b#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="被低估的ai原生markdown神器" tabindex="-1"><a class="header-anchor" href="#被低估的ai原生markdown神器"><span>被低估的AI原生Markdown神器</span></a></h3><p>开源君：很多人找兼顾美观编辑、AI辅助、本地存储的Markdown笔记工具，OpenKnowledge刚好满足，免费开源私有，支持多端多AI接入，适合个人团队做知识管理。<a href="https://mp.weixin.qq.com/s?__biz=MzkwNzU4NTMyMA==&amp;chksm=c117ad80086dd90a0737e51ea0c568d3aef53797a0feb26906691c2af6abb4f1bf7e6b3e0f45&amp;idx=1&amp;mid=2247508290&amp;sn=3e392102e4c0ed6e65ea539eea0c8855#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="寿政-打造下一代具身大模型底座" tabindex="-1"><a class="header-anchor" href="#寿政-打造下一代具身大模型底座"><span>寿政：打造下一代具身大模型底座</span></a></h3><p>NUS寿政教授打破传统模型拼接套路，在单个Transformer中融合自回归与离散扩散，用循环一致性监督解决数据稀缺，靠自研骨干网实现低延迟，打造适配具身智能的统一大模型底座。<a href="https://mp.weixin.qq.com/s?__biz=MzA5ODEzMjIyMA==&amp;chksm=914308c6dd26c64966cba7599ec79a21f66384b1b4e2aeb42ba0c32092606012c1d957f65368&amp;idx=2&amp;mid=2247745001&amp;sn=afb488fbea0645036a5b57ab2fe96609#rd" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',45)]))}const t=a(i,[["render",c]]),l=JSON.parse('{"path":"/posts/2026-09-11.html","title":"AI日报：王梦迪：AI尚未发现新基础科学; 汤森路透推出领域定制大模型; 人形机器人IPO收紧 刚上市CEO炮轰同行","lang":"zh-CN","frontmatter":{"date":"2026-09-11T00:00:00.000Z","title":"AI日报：王梦迪：AI尚未发现新基础科学; 汤森路透推出领域定制大模型; 人形机器人IPO收紧 刚上市CEO炮轰同行"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"王梦迪：AI尚未发现新基础科学","slug":"王梦迪-ai尚未发现新基础科学","link":"#王梦迪-ai尚未发现新基础科学","children":[]},{"level":3,"title":"汤森路透推出领域定制大模型","slug":"汤森路透推出领域定制大模型","link":"#汤森路透推出领域定制大模型","children":[]},{"level":3,"title":"人形机器人IPO收紧 刚上市CEO炮轰同行","slug":"人形机器人ipo收紧-刚上市ceo炮轰同行","link":"#人形机器人ipo收紧-刚上市ceo炮轰同行","children":[]},{"level":3,"title":"中国智驾叩开欧洲车企供应链大门","slug":"中国智驾叩开欧洲车企供应链大门","link":"#中国智驾叩开欧洲车企供应链大门","children":[]},{"level":3,"title":"OpenAI杀疯 欲破千禧年数学难题","slug":"openai杀疯-欲破千禧年数学难题","link":"#openai杀疯-欲破千禧年数学难题","children":[]},{"level":3,"title":"陶哲轩怒批OpenAI毁数学开放传统","slug":"陶哲轩怒批openai毁数学开放传统","link":"#陶哲轩怒批openai毁数学开放传统","children":[]},{"level":3,"title":"Anthropic推演：AI时代钱流向有钱人","slug":"anthropic推演-ai时代钱流向有钱人","link":"#anthropic推演-ai时代钱流向有钱人","children":[]},{"level":3,"title":"张天翊打造数字世界个人AI身份证","slug":"张天翊打造数字世界个人ai身份证","link":"#张天翊打造数字世界个人ai身份证","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"Snowflake入华两年押注企业智能体","slug":"snowflake入华两年押注企业智能体","link":"#snowflake入华两年押注企业智能体","children":[]},{"level":3,"title":"豆包工作上新三大功能 主打无痛办公","slug":"豆包工作上新三大功能-主打无痛办公","link":"#豆包工作上新三大功能-主打无痛办公","children":[]},{"level":3,"title":"iRobot重返IFA 二次定义清洁机器人","slug":"irobot重返ifa-二次定义清洁机器人","link":"#irobot重返ifa-二次定义清洁机器人","children":[]},{"level":3,"title":"DeepSeek V4.1 Flash 成显存杀手","slug":"deepseek-v4-1-flash-成显存杀手","link":"#deepseek-v4-1-flash-成显存杀手","children":[]},{"level":3,"title":"Meta推Muse：AI全天候替你干活","slug":"meta推muse-ai全天候替你干活","link":"#meta推muse-ai全天候替你干活","children":[]},{"level":3,"title":"京东发布狼族军团重做物理AI","slug":"京东发布狼族军团重做物理ai","link":"#京东发布狼族军团重做物理ai","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"英伟达CPO量产 光模块还能打吗？","slug":"英伟达cpo量产-光模块还能打吗","link":"#英伟达cpo量产-光模块还能打吗","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"SGLang优化DeepSeek-V4.1达764 tokens/s","slug":"sglang优化deepseek-v4-1达764-tokens-s","link":"#sglang优化deepseek-v4-1达764-tokens-s","children":[]},{"level":3,"title":"被低估的AI原生Markdown神器","slug":"被低估的ai原生markdown神器","link":"#被低估的ai原生markdown神器","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"寿政：打造下一代具身大模型底座","slug":"寿政-打造下一代具身大模型底座","link":"#寿政-打造下一代具身大模型底座","children":[]}]}],"git":{"updatedTime":1789463450000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"cebe2637b14036c2f68716177bcf307b8091e50c","time":1789463450000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-09-15T09:10:50.106Z"}]},"filePathRelative":"posts/2026-09-11.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-09-11 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>王梦迪：AI尚未发现新基础科学</h3>\\n<p>王梦迪：当前大模型偏向拟合概率分布中心，低估长尾情况；因基础科研缺乏成熟验证器，AI尚未发现新基础科学，需搭建可验证可复现的科研基础设施。<a href=\\"https://mp.weixin.qq.com/s?__biz=MzU1NDA4NjU2MA==&amp;chksm=faebba21f25db7451d8eb353f8b1ac4f0d3fa02d57ba287980c69cb6cb5fda76dd35babee4b6&amp;idx=2&amp;mid=2247666942&amp;sn=9852c672d6b4d5e75a1b9ed102e7e347#rd\\" target=\\"_blank\\" rel=\\"noopener noreferrer\\">&gt;阅读原文</a></p>"}');export{t as comp,l as data};
